/* Bank soal LISTENING tingkat SULIT (3) dan SANGAT SULIT (4), gaya TOEFL ITP / ELPT / AcEPT.
 * Part A  : dialog pendek dengan makna tersirat, idiom, pengandaian, negasi ganda, dan sindiran.
 * Part B  : percakapan panjang (passage audio LB*), satu audio untuk 4 soal.
 * Part C  : kuliah/pengumuman akademik (passage audio LC*), satu audio untuk 4 soal.
 * au: [['W'|'M'|'N', kalimat]] → W = woman, M = man, N = narator. Transkrip baru tampil setelah ujian selesai.
 * Format: helper L(kalimat1, kalimat2, pertanyaan, [BENAR, pengecoh...], pembahasan, priaDuluan).
 */
const L = (s1, s2, q, o, e, firstMan) => ({ au: firstMan ? [['M', s1], ['W', s2]] : [['W', s1], ['M', s2]], q, o, a: 0, e });
